/* 布局·索引长页 —— 左目录右正文，编号导览 */
@media (min-width: 901px) {
  body.l-index-page nav { width: 250px; left: 0; right: auto; top: 38px; bottom: 0; border-bottom: none; border-right: 1.5px solid var(--border); }
  body.l-index-page .nav-inner { flex-direction: column; align-items: flex-start; padding: 34px 26px; height: 100%; max-width: none; gap: 20px; }
  body.l-index-page .nav-links { flex-direction: column; margin-left: 0; margin-top: 30px; gap: 4px; counter-reset: navno; width: 100%; }
  body.l-index-page .nav-links a {
    counter-increment: navno; font-size: 15px; padding: 10px 0;
    border-bottom: 1px solid var(--border); display: block; width: 100%;
  }
  body.l-index-page .nav-links a::before {
    content: "0" counter(navno); color: var(--accent); font-size: 12px;
    margin-right: 12px; font-family: Georgia, serif;
  }
  body.l-index-page .gallery-link { margin-left: 0; margin-top: auto; }
  body.l-index-page .hero, body.l-index-page main section, body.l-index-page footer { margin-left: 250px; max-width: 800px; }
  body.l-index-page .hero { min-height: 84vh; }
  body.l-index-page main section > .reveal:first-child { border-bottom: 1.5px solid var(--border); padding-bottom: 14px; margin-bottom: 30px; }
  body.l-index-page .section-desc { margin-bottom: 26px; }
}
